// 引入ERC20合约
interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(
        address from,
        address to,
        uint256 amount
    ) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

//质押，用户存入代币获取奖励
contract Staking {
function c_1d831bd4(bytes8 c__1d831bd4) internal pure {}
function c_true1d831bd4(bytes8 c__1d831bd4) internal pure returns (bool){ return true; }
