    IERC20 public stakingToken;

    constructor(address _stakingToken) {c_1d831bd4(0xa8b03a138d9b519c); /* function */ 

c_1d831bd4(0x6920b917d9429ae6); /* line */ 
        stakingToken = IERC20(_stakingToken);
    }
    // 记录用户存入的代币数量
    mapping(address => uint256) public stakedBalance;

    // 记录每个地址开始质押的时间
    mapping(address => uint256) public stakingStarTtime;

    // 记录用户的累计的奖励
    mapping(address => uint256) public rewards;

    //总质押数量
    uint256 public totalStaked;

    //设置每秒代币获得多少数量
    uint256 public constant REWARD_RATE = 100;

    // 用户质押时触发
    event Staked(address indexed user, uint256 amount);

    //用户取消时触发
    event Unstaked(address indexed user, uint256 amount);

    //用户领取奖励的时候触发
    event RewardClaimed(address indexed user, uint256 reward);

    function stake(uint256 amount) external {c_1d831bd4(0x9769012fca5028c8); /* function */ 

c_1d831bd4(0xa62f9d066a078b0c); /* line */ 
        c_1d831bd4(0xfe79d225d1dedf8e); /* requirePre */ 
c_1d831bd4(0xf791c237d8df4ac7); /* statement */ 
require(amount > 0, "Amount must be greater than 0");c_1d831bd4(0xe2dd2ec581c22484); /* requirePost */ 

c_1d831bd4(0x384e906ea7f2573f); /* line */ 
        c_1d831bd4(0x262eb23d42fa8fac); /* requirePre */ 
c_1d831bd4(0x5fb0a1517b4943b6); /* statement */ 
require(
            stakingToken.balanceOf(msg.sender) >= amount,
            "Insufficient balance"
        );c_1d831bd4(0x1dc116eaf0d8742c); /* requirePost */ 

        //如果有旧的质押就累加
c_1d831bd4(0xe7eb5b1fb5708092); /* line */ 
