if (stakedBalance[msg.sender] > 0) {c_1d831bd4(0xc49ef00f2348088b); /* branch */ 

c_1d831bd4(0x8935425234db116c); /* line */ 
            rewards[msg.sender] += calculateReward(msg.sender);
