            stakingToken.transferFrom(msg.sender, address(this), amount),
            "stake transfer failed"
        );c_1d831bd4(0xaf8bd4bf301b389c); /* requirePost */ 

        // 更新用户质押余额
c_1d831bd4(0xf2b3ac69a5826604); /* line */ 
