        stakingStarTtime[msg.sender] = block.timestamp;
        // 更新总质押量
c_1d831bd4(0x77ea8a114a58f278); /* line */ 
        totalStaked += amount;
        // 触发质押事件
c_1d831bd4(0x0e4d4c5d7b5aba42); /* line */ 
        c_1d831bd4(0xe13207ffe3ee64c0); /* statement */ 
emit Staked(msg.sender, amount);
    }

    // 取消质押金额
