        // 先看累计了多少奖励
c_1d831bd4(0x1fe99ec99060f7d7); /* line */ 
        rewards[msg.sender] += calculateReward(msg.sender);
c_1d831bd4(0xb04096a4c4a871eb); /* line */ 
        stakedBalance[msg.sender] -= amount;
c_1d831bd4(0xf1c2128ab1c5bd1d); /* line */ 
        stakingStarTtime[msg.sender] = block.timestamp;
c_1d831bd4(0x92e33bf15f438cc5); /* line */ 
        totalStaked -= amount;
c_1d831bd4(0xe4cbc7622c3f8f97); /* line */ 
        c_1d831bd4(0x9b1bc07b12689a17); /* requirePre */ 
c_1d831bd4(0x82c3ec65001d89d8); /* statement */ 
require(
            stakingToken.transfer(msg.sender, amount),
            "Unstake transfer failed"
        );c_1d831bd4(0xd89b2f3f73c65786); /* requirePost */ 

c_1d831bd4(0xd7c8e4c8b47e47eb); /* line */ 
        c_1d831bd4(0xfec4915b53499309); /* statement */ 
emit Unstaked(msg.sender, amount);
    }

    function claimReward() external {c_1d831bd4(0x92919ad861f308c1); /* function */ 

        // 计算总奖励=待计算奖励+已累计的奖励
c_1d831bd4(0xcc90015e1030ce0d); /* line */ 
        c_1d831bd4(0xad218a92458786c5); /* statement */ 
uint256 reward = calculateReward(msg.sender) + rewards[msg.sender];
        // 检查
c_1d831bd4(0x3aef28915a0e770f); /* line */ 
        c_1d831bd4(0x7db1433e00c3145a); /* requirePre */ 
c_1d831bd4(0x0d4c4cdac992cb19); /* statement */ 
require(reward > 0, "No rewards to claim");c_1d831bd4(0x7340aa9d96e6907b); /* requirePost */ 

        // 已领取后重置时间和奖励金额
c_1d831bd4(0xdc964957170c7908); /* line */ 
        rewards[msg.sender] = 0;
c_1d831bd4(0xdda8e1fc933104bc); /* line */ 
        stakingStarTtime[msg.sender] = block.timestamp;
        // 奖励
c_1d831bd4(0x2217d574d5a0bb4d); /* line */ 
        c_1d831bd4(0xad3371089ddb6d6e); /* requirePre */ 
c_1d831bd4(0x7602a45148bdc47e); /* statement */ 
require(
            stakingToken.transfer(msg.sender, reward),
            "Reward transfer failed"
        );c_1d831bd4(0x8c264204f505e298); /* requirePost */ 

c_1d831bd4(0xe4c66de9e2809d43); /* line */ 
        c_1d831bd4(0xf3660c2ff3ead1eb); /* statement */ 
emit RewardClaimed(msg.sender, reward);
    }

    function calculateReward(address user) public view returns (uint256) {c_1d831bd4(0x8e0f8d2a95d13606); /* function */ 

c_1d831bd4(0x68974e634a2e982a); /* line */ 
        c_1d831bd4(0xff9c3cb81d9c24ec); /* statement */ 
if (stakedBalance[user] == 0) {c_1d831bd4(0xb942c71d51d3eb3c); /* branch */ 

c_1d831bd4(0x55985789b761100d); /* line */ 
            c_1d831bd4(0x111be2dea7a67b62); /* statement */ 
return 0;
        }else { c_1d831bd4(0xd9b1c6862c1b6696); /* branch */ 
}
c_1d831bd4(0x476c63e928ad25a7); /* line */ 
        c_1d831bd4(0x58671e343047d7c3); /* statement */ 
uint256 stakingDuration = block.timestamp - stakingStarTtime[user];

        // 使用分钟或小时为单位，减少精度敏感性(不这样测试会先调用)
c_1d831bd4(0x00baad5c4bba5420); /* line */ 
        c_1d831bd4(0x2ebd2aa61b579969); /* statement */ 
uint256 durationInMinutes = stakingDuration / 60;
c_1d831bd4(0xb2fed70fcb0cb04e); /* line */ 
        c_1d831bd4(0xfe2225620900f379); /* statement */ 
if (durationInMinutes == 0) {c_1d831bd4(0xe8a69334fea2688a); /* branch */ 

c_1d831bd4(0x70465e779dd9e83f); /* line */ 
            c_1d831bd4(0xabb07e19e0f07f3b); /* statement */ 
return 0;
        }else { c_1d831bd4(0xf2f2fe37eca19519); /* branch */ 
}
        // 计算奖励：质押金额 * 持续时间(分钟) * 奖励率
c_1d831bd4(0xfbd0eac3a9bbee84); /* line */ 
        c_1d831bd4(0xd95525bbccbd8291); /* statement */ 
return (stakedBalance[user] * durationInMinutes * REWARD_RATE) / 1e18;
    }

    // 获取总奖励函数：返回用户的总奖励（待计算 + 已累积）
    function getTotalRewards(address user) public view returns (uint256) {c_1d831bd4(0x940a7a95eb673f35); /* function */ 

c_1d831bd4(0x52ef687b06b28ecf); /* line */ 
        c_1d831bd4(0xf146fddd3482194d); /* statement */ 
return calculateReward(user) + rewards[user];
    }
}

